def changed(data, marker, key, value, occurrence=0):
    rows=data.decode().splitlines();matches=[index for index,row in enumerate(rows) if row.startswith(marker+' ')]
    index=matches[occurrence];pattern=r'(?<= )'+re.escape(key)+r'=[^ ]+'
    rows[index],count=re.subn(pattern,key+'='+str(value),rows[index]);assert count==1
    return ('\n'.join(rows)+'\n').encode()


def user(data, marker, key, value, occurrence=0):
    return changed(data,'TESSRYN_K03_SMP_USER_'+marker,key,value,occurrence)


def field(data, marker, key, occurrence=0):
    rows=[row for row in data.decode().splitlines() if row.startswith('TESSRYN_K03_SMP_USER_'+marker+' ')]
    value=re.search(r'(?<= )'+re.escape(key)+r'=([^ ]+)',rows[occurrence])[1]
    return int(value,16 if value.startswith('0x') else 10)


class SmpUserTraceTests(unittest.TestCase):
    def parse(self, data=None, case='rendezvous', binding=None):
        return parse_transcript(case,TRACES[case] if data is None else data,33,b'',BINDINGS[case] if binding is None else binding)

    def reject(self,data,case='rendezvous'):
        with self.assertRaises(ValueError):self.parse(data,case)

    def test_three_actual_diagnostic_fixtures_have_distinct_bound_outcomes(self):
        values=[self.parse(case=case) for case in CASES]
        self.assertEqual([row['ipi_acknowledgments'] for row in values],[2,1,1])
        self.assertEqual([row['user_traps'] for row in values],[3,2,2])
        self.assertEqual([row['protection_fault'] for row in values],[None,'page-fault','general-protection'])
        self.assertTrue(values[0]['ap_heartbeat']>65536)
        self.assertEqual([row['ap_heartbeat'] for row in values[1:]],[0,0])
        self.assertTrue(all(row['capture_authentication']=='unverified_offline' for row in values))

    def test_process_completion_stderr_ascii_and_case_identity_are_required(self):
        for code,stderr in ((None,b''),(True,b''),(0,b''),(33,b'host diagnostic')):
            with self.subTest(code=code),self.assertRaises(ValueError):
                parse_transcript('rendezvous',TRACES['rendezvous'],code,stderr,BINDINGS['rendezvous'])
        self.reject(TRACES['rendezvous'][:-1]);self.reject(TRACES['rendezvous']+b'\xff\n')
        self.reject(TRACES['rendezvous']+b'TESSRYN_K01_EXCEPTION vector=6\n')
        self.reject(user(TRACES['rendezvous'],'BEGIN','case','peer_read'))
        self.reject(changed(TRACES['rendezvous'],'TESSRYN_K03_SMP_BEGIN','case','missing_ap'))

    def test_records_are_ordered_complete_unique_and_canonical(self):
        raw=TRACES['rendezvous'];line=next(row for row in raw.splitlines(keepends=True) if row.startswith(b'TESSRYN_K03_SMP_USER_WALK'))
        for data in (raw.replace(line,b'',1),raw.replace(line,line+line,1),raw.replace(b'cpus=2',b'cpus=2 extra=1',1),
                     raw.replace(b'cpus=2',b'cpus=2 cpus=2',1),raw.replace(b'cpus=2',b' cpus=2',1)):
            with self.subTest(tail=data[-60:]):self.reject(data)

    def test_compiled_payload_case_descriptor_labels_and_gs_reload_are_required(self):
        for mutate in (lambda b:b['descriptor'].update(sha256='0'*64),lambda b:b['program'].update(size_bytes=4095),
                       lambda b:b['program']['offsets'].update(loop_start=True),lambda b:b['program']['offsets'].update(after_yield=40),
                       lambda b:b['program']['instruction_bytes'].update(bsp_start='0'*32),
                       lambda b:b['program']['instruction_bytes'].update(peer_fault='0'*32),
                       lambda b:b['bootstrap'].update(image_size=4096)):
            binding=copy.deepcopy(BINDINGS['rendezvous']);mutate(binding)
            with self.assertRaises(ValueError):self.parse(binding=binding)
        with self.assertRaises(ValueError):self.parse(binding=BINDINGS['peer_read'])

    def test_each_cpu_owns_distinct_complete_roots_backings_and_private_descriptors(self):
        raw=TRACES['rendezvous']
        for key in ('root','code_phys','stack_phys','data_phys','gdt','idt','tss','context','trap_start','fault_start'):
            value=field(raw,'SPACE',key)
            with self.subTest(key=key):self.reject(user(raw,'SPACE',key,hex(value),1))
        for key,value in (('root_end',0),('leaves',4),('peer_phys',field(raw,'SPACE','peer_phys')),
                          ('trap_end',field(raw,'SPACE','trap_end',1)-4096),('code_phys',1)):
            with self.subTest(key=key):self.reject(user(raw,'SPACE',key,hex(value),1))

    def test_actual_privileged_state_readback_gs_and_feature_admission_are_required(self):
        raw=TRACES['rendezvous'];state0=field(raw,'STATE','gsbase')
        for key,value in (('gsbase',state0),('user_gsbase',1),('gdt',field(raw,'STATE','gdt')),('idt',0),('tss',0),
                          ('tr',40),('ldtr',8),('dr7',0x401),('efer',0xd01),('efer',0x500),('cr0',0x80000033)):
            with self.subTest(key=key,value=value):self.reject(user(raw,'STATE',key,hex(value),1))
        for bit in (7,8,12,16,17,18,22,23,24):
            self.reject(user(raw,'STATE','cr4',hex(field(raw,'STATE','cr4',1)|(1<<bit)),1))

    def test_raw_user_walks_bind_effective_permissions_backings_and_supervisor_aliases(self):
        raw=TRACES['rendezvous']
        for occurrence,key,mask in ((0,'e3',2),(0,'e3',1<<63),(0,'e0',4),(1,'e3',1<<63),(2,'e3',2),
                                    (3,'e3',2),(4,'e2',4),(7,'e2',8),(8,'e2',1<<63)):
            value=field(raw,'WALK',key,occurrence)^mask
            with self.subTest(occurrence=occurrence,key=key):self.reject(user(raw,'WALK',key,hex(value),occurrence))
        self.reject(user(raw,'WALK','e3',hex(field(raw,'SPACE','code_phys',1)|5),0))

    def test_raw_walk_child_links_stay_in_hardware_pool_and_are_consistent(self):
        raw=TRACES['rendezvous'];root=field(raw,'SPACE','root')
        for key,value in (('t0',root+4096),('t1',root),('e0',root|7),('t3',root+16*4096),('e2',(root+16*4096)|7),('e1',1<<52)):
            with self.subTest(key=key):self.reject(user(raw,'WALK',key,hex(value),0))
        self.reject(user(raw,'WALK','e0',hex(field(raw,'WALK','e0',1)^4),1))

    def test_ap_peer_page_is_absent_at_actual_zero_pde_and_has_no_trailing_walk(self):
        raw=TRACES['peer_read'];occurrence=12
        self.assertEqual(field(raw,'WALK','e2',occurrence),0)
        for key,value in (('e2',7),('t3',field(raw,'SPACE','root',1)+8*4096),('e3',field(raw,'SPACE','peer_phys')|5)):
            with self.subTest(key=key):self.reject(user(raw,'WALK',key,hex(value),occurrence),'peer_read')

    def test_raw_cpl3_frame_and_fp_area_are_exactly_on_own_tss_stack(self):
        raw=TRACES['rendezvous']
        for key,value in (('cs',8),('ss',16),('rsp',PROFILE['user_stack']),('root',field(raw,'SPACE','root')),
                          ('apic',0),('frame',field(raw,'TRAP','frame')-8),('fp',field(raw,'TRAP','fp')+16),
                          ('kernel_rsp',field(raw,'TRAP','kernel_rsp',1)),('kernel_cr3',field(raw,'SPACE','root',1))):
            with self.subTest(key=key):self.reject(user(raw,'TRAP',key,hex(value),0))
        for bit in (8,10,12,13,14,17,18,19,20):
            self.reject(user(raw,'TRAP','rflags',hex(field(raw,'TRAP','rflags')|(1<<bit)),0))

    def test_full_gpr_and_fp_images_match_each_cpu_and_all_preserved_registers(self):
        raw=TRACES['rendezvous']
        trap=next(row for row in raw.decode().splitlines() if ' stage=warmup ' in row)
        for key,index in (('gpr',0),('gpr',2*8),('gpr',13*8),('fp_image',0),('fp_image',24),('fp_image',29),('fp_image',160),('fp_image',300)):
            image=re.search(r' '+key+r'=([^ ]+)',trap)[1];data=bytearray.fromhex(image);data[index]^=1
            with self.subTest(key=key,index=index):self.reject(user(raw,'TRAP',key,data.hex()))
        for key,value in (('r12',0),('r13',0),('xmm0lo',0),('xmm0hi',0),('marker',0)):
            self.reject(user(raw,'TRAP',key,value))

    def test_each_hardware_ipi_requires_source_isr_eoi_generation_and_bound_instruction(self):
        raw=TRACES['rendezvous']
        for occurrence in (1,2):
            for key,value in (('vector',64),('error',1),('isr_before',0),('isr_after',4),('generation',0),('heartbeat',0)):
                with self.subTest(occurrence=occurrence,key=key):self.reject(user(raw,'TRAP',key,value,occurrence))
            for offset in range(8):
                data=user(raw,'TRAP','rip',hex(PROFILE['user_code']+BINDINGS['rendezvous']['program']['offsets']['loop_start']+offset),occurrence)
                with self.subTest(occurrence=occurrence,offset=offset):
                    if offset in (0,4,6):self.parse(data)
                    else:self.reject(data)
        self.parse(user(raw,'TRAP','heartbeat',field(raw,'OVERLAP','bsp_after'),1))

    def test_actual_fault_instructions_vectors_errors_and_cr2_cannot_be_relabelled(self):
        for case,mutations in (('peer_read',(('error',0),('vector',13),('cr2',PROFILE['user_data']),('rip',PROFILE['user_code']))),
                               ('forged_ipi',(('error',0x202),('vector',66),('isr_before',4),('generation',1),('rip',PROFILE['user_code'])))):
            for key,value in mutations:
                with self.subTest(case=case,key=key):self.reject(user(TRACES[case],'TRAP',key,hex(value)),case)

    def test_overlap_warmup_and_post_fault_bsp_progress_are_real_and_ordered(self):
        raw=TRACES['rendezvous']
        for key,value in (('bsp_after',field(raw,'OVERLAP','bsp_before')),('ap_before',1),('ap_after',65535),('end',field(raw,'OVERLAP','start'))):
            self.reject(user(raw,'OVERLAP',key,value))
        self.reject(user(raw,'TRAP','heartbeat',65535));self.reject(user(raw,'TRAP','rip',PROFILE['user_code']))
        for case in ('peer_read','forged_ipi'):
            raw=TRACES[case]
            for key,value in (('after',field(raw,'FAULT_PROGRESS','before')),('start',field(raw,'OVERLAP','end')-1),
                              ('end',field(raw,'FAULT_PROGRESS','start')+1)):
                with self.subTest(case=case,key=key):self.reject(user(raw,'FAULT_PROGRESS',key,value),case)
            self.reject(user(raw,'TRAP','heartbeat',field(raw,'FAULT_PROGRESS','after')-1,1),case)

    def test_terminal_ack_stability_retained_memory_payloads_and_no_later_progress(self):
        for case in CASES:
            raw=TRACES[case]
            for key,value in (('generation',0),('stable',field(raw,'STOP','heartbeat')+1),('end',field(raw,'STOP','start')+1),('start',0)):
                with self.subTest(case=case,key=key):self.reject(user(raw,'STOP',key,value),case)
            self.reject(user(raw,'PAYLOAD','sha256','0'*64,3),case)
            self.reject(raw+b'TESSRYN_K03_SMP_USER_PASS cpus=2 ipis=2 faults=0 retained=all\n',case)

if __name__=='__main__':unittest.main()
